(function(root) {
    'use strict';

    function Grid(element, options) {
        this.element = element;
        this.options = options || {};
        this.rowData = options.rowData || [];
        this.columnDefs = options.columnDefs || [];
        this.api = new GridApi(this);
        this._render();
    }

    function GridApi(grid) {
        this._grid = grid;
    }

    GridApi.prototype.setRowData = function(data) {
        this._grid.rowData = data || [];
        this._grid._render();
    };

    GridApi.prototype.setColumnDefs = function(defs) {
        this._grid.columnDefs = defs || [];
        this._grid._render();
    };

    GridApi.prototype.sizeColumnsToFit = function() {};
    GridApi.prototype.destroy = function() {
        this._grid.element.innerHTML = '';
    };

    GridApi.prototype.exportDataAsCsv = function(params) {
        var data = this._grid.rowData;
        var cols = this._grid.columnDefs;
        var sep = (params && params.columnSeparator) || ',';
        var lines = [];

        var header = cols.map(function(c) { return c.headerName || c.field || ''; });
        lines.push(header.join(sep));

        data.forEach(function(row) {
            var vals = cols.map(function(c) {
                var v = row[c.field];
                return v != null ? String(v) : '';
            });
            lines.push(vals.join(sep));
        });

        return lines.join('\n');
    };

    Grid.prototype._render = function() {
        var el = this.element;
        var cols = this.columnDefs;
        var data = this.rowData;
        var opts = this.options;

        el.innerHTML = '';
        el.style.overflow = 'auto';
        el.style.fontSize = '0.85rem';

        var table = document.createElement('table');
        table.className = 'table table-sm table-striped table-bordered mb-0';

        var thead = document.createElement('thead');
        thead.style.position = 'sticky';
        thead.style.top = '0';
        thead.style.zIndex = '1';
        var tr = document.createElement('tr');
        cols.forEach(function(col) {
            var th = document.createElement('th');
            th.textContent = col.headerName || col.field || '';
            th.style.whiteSpace = 'nowrap';
            th.style.background = 'var(--bs-table-bg, #fff)';
            if (col.width) th.style.width = col.width + 'px';
            tr.appendChild(th);
        });
        thead.appendChild(tr);
        table.appendChild(thead);

        var tbody = document.createElement('tbody');
        var pageSize = (opts.paginationPageSize) || 100;
        var maxRows = Math.min(data.length, opts.pagination ? pageSize : data.length);

        for (var i = 0; i < maxRows; i++) {
            var row = data[i];
            var rowTr = document.createElement('tr');

            if (row._subtotal) {
                rowTr.style.fontWeight = 'bold';
                rowTr.style.background = 'var(--bs-tertiary-bg, #f0f0f0)';
            }

            cols.forEach(function(col) {
                var td = document.createElement('td');
                var val = row[col.field];
                if (val != null) {
                    if (typeof val === 'number' && col.valueFormatter) {
                        td.textContent = col.valueFormatter({ value: val });
                    } else {
                        td.textContent = val;
                    }
                    if (typeof val === 'number') td.style.textAlign = 'right';
                }
                td.style.whiteSpace = 'nowrap';
                rowTr.appendChild(td);
            });
            tbody.appendChild(rowTr);
        }
        table.appendChild(tbody);
        el.appendChild(table);

        if (data.length > maxRows && opts.pagination) {
            var info = document.createElement('div');
            info.className = 'text-muted text-center py-1';
            info.style.fontSize = '0.75rem';
            info.textContent = 'Mostrando ' + maxRows + ' de ' + data.length + ' linhas';
            el.appendChild(info);
        }
    };

    function createGrid(element, options) {
        var grid = new Grid(element, options);
        return grid.api;
    }

    root.agGrid = {
        Grid: Grid,
        createGrid: createGrid
    };

    if (typeof module !== 'undefined' && module.exports) module.exports = root.agGrid;
})(typeof window !== 'undefined' ? window : this);
